def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Dense rows are horizontal bars; fill single-cell gaps within each bar.
    bar_rows = {r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 3}
    gap_seeds = []
    for r in bar_rows:
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r][c - 1] != 0 and grid[r][c + 1] != 0:
                if grid[r][c - 1] == grid[r][c + 1]:
                    out[r][c] = grid[r][c - 1]
                    gap_seeds.append((r, c, out[r][c]))

    # Vertical markers below bars, and filled bar gaps, extend upward until
    # they meet another colored cell.
    seeds = list(gap_seeds)
    for r in range(h):
        if r not in bar_rows:
            for c in range(w):
                if grid[r][c] != 0:
                    seeds.append((r, c, grid[r][c]))

    for r, c, color in seeds:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    return out
